import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.2.0/src/p5.flex.min.mjs"
/* [Inlined Multi-Tab] Control.js */
/* [Inlined Multi-Tab] shader.js */

mountFlex(p5)
mountControl(p5)

new p5((p) => {
	const [WIDTH, HEIGHT] = [1024, 576]
	const PIXEL_DENSITY = 1
	const CANVAS_SIZE = [WIDTH, HEIGHT]
	let gfx, res, theShader, filterShader

	let STYLE = 0
	let MONOCHROME = false

    const charSize = HEIGHT * 0.75
	let isBorder = false
	let index = 0
	let [pStatus, status] = [0, 0]

	p.setup = () => {
		p.createCanvas(WIDTH, HEIGHT)
		p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })
		p.pixelDensity(PIXEL_DENSITY)

		gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)
		res = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)
		theShader = p.createShader(VERT, FRAG)
		filterShader = p.createShader(VERT, FILTER_FRAG)

		p.noStroke()
		gfx.noStroke()

		p.PressDo("s", () => (STYLE = (STYLE + 1) % 4))
		p.PressDo("m", () => (MONOCHROME = !MONOCHROME))
		p.PressLoopToggle(" ")
	}

	p.draw = () => {
		const t = p.frameCount / 60

        const st = slideTrans(0.5 * t) // 0.9 控制展现速度
		const color = 255 * p.lerp(0, 1.5, st)
		;[pStatus, status] = [status, st]
		status < pStatus && (index += 1)
        char(WIDTH / 2, HEIGHT / 2, charSize, color, 2)

		gfx.shader(theShader)
		theShader.setUniform("tex0", gfx)
		theShader.setUniform("canvasSize", CANVAS_SIZE)
		theShader.setUniform("mouse", [p.mouseX / WIDTH, p.mouseY / HEIGHT])
		theShader.setUniform("time", t)
		gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		res.shader(filterShader)
		filterShader.setUniform("tex0", gfx)
		filterShader.setUniform("canvasSize", CANVAS_SIZE)
		filterShader.setUniform("mouse", [p.mouseX / WIDTH, p.mouseY / HEIGHT])
		filterShader.setUniform("time", t)
		filterShader.setUniform("iStyle", STYLE)
		filterShader.setUniform("iMonochrome", MONOCHROME)
		res.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		p.image(res, 0, 0)
	}


    const char = (w, h, size, color, thickness) => {
		p.push()
		p.stroke(color, color)
		p.noFill()
		p.strokeWeight(thickness)
		p.textSize(size)
		p.textAlign(p.CENTER, p.CENTER)
		p.textFont("標楷體")
		p.text("L", w, h)
		p.pop()
	}

    const slideTrans = (t) =>
		p.floor(t % 2)
			? 0.5 + 0.5 * p.cos(p.PI * t)
			: 0.5 + 0.5 * p.cos(p.PI * t + p.PI)

	const Border = (color, weight) => {
		p.push()
		p.noFill()
		p.stroke(color)
		p.strokeWeight(weight * 2)
		p.rectMode(p.CENTER)
		p.rect(WIDTH / 2, HEIGHT / 2, WIDTH, HEIGHT)
		p.pop()
	}
})



